/**
 * AUTHORSED SOURCE - NOT A BUILD OUTPUT.
 *
 * lib/client.js and lib/pele-runtime.js are generated by scripts/build.mjs, but this
 * host half is hand-written and must survive a clean rebuild. scripts/build.mjs fails
 * fast when it is missing; never delete lib/ to force a rebuild.
 */
import { readFile } from 'node:fs/promises';

/** Cordis services the host half depends on. */
export const inject = ['webServer'];

/** Public URL of the lazily loaded Pele browser runtime. */
export const RUNTIME_PATH = '/dsh-pele-mermaid/pele-runtime.js';

/** Absolute location of the shipped Pele global bundle. */
export const RUNTIME_FILE = new URL('./pele-runtime.js', import.meta.url);

/** One year of immutable caching; the file is versioned by the package release. */
export const CACHE_CONTROL = 'public, max-age=31536000, immutable';

/**
 * Build the HTTP handler for the Pele runtime route.
 * @param {() => Promise<Buffer|string>} [readRuntime] test seam for the 404 branch
 */
export function createRuntimeHandler(readRuntime = () => readFile(RUNTIME_FILE)) {
  return async function peleRuntimeHandler(req, res) {
    const requested = (req && typeof req.url === 'string') ? req.url : '';
    if (requested) {
      let pathname = requested;
      const cut = pathname.search(/[?#]/);
      if (cut !== -1) pathname = pathname.slice(0, cut);
      if (/^[a-z][a-z0-9+.-]*:\/\//i.test(pathname)) {
        try { pathname = new URL(pathname).pathname; } catch { pathname = ''; }
      }
      if (pathname !== RUNTIME_PATH) {
        res.writeHead(404);
        res.end();
        return;
      }
    }
    const method = (req && typeof req.method === 'string') ? req.method.toUpperCase() : 'GET';
    if (method !== 'GET' && method !== 'HEAD') {
      res.writeHead(405);
      res.end();
      return;
    }
    let body;
    try {
      body = await readRuntime();
    } catch {
      res.writeHead(404);
      res.end();
      return;
    }
    res.writeHead(200, {
      'content-type': 'text/javascript; charset=utf-8',
      'cache-control': CACHE_CONTROL,
    });
    res.end(method === 'HEAD' ? undefined : body);
  };
}

/** Register the runtime route with the DSH web server. */
export function apply(ctx) {
  ctx.effect(() => ctx.webServer.register({
    kind: 'exact',
    path: RUNTIME_PATH,
    handler: createRuntimeHandler(),
  }), 'dsh-pele-mermaid: runtime route');
}
